-- 2) NEW 1008
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1008, 'AMA+ Scholarship (Art Major Asian plus) at Korea National University of Arts', 'Korea National University of Arts (K-Arts)', 'South Korea', 'Full Tuition + Stipend', 0, 'Annual May online application window (the application link is open only during the window). For the 2027 intake: guideline released April 2026, online application 5-15 May 2026, final grantees announced 30 June 2026, original documents due by 31 July 2026, entry to Korea late August / late November 2026 for pre-entry Korean training. The 2028-intake guideline and dates have not been published yet.', '["Bachelor","Master"]', '["Music","Drama","Film, TV & Multimedia","Dance","Visual Arts","Korean Traditional Arts"]', NULL, NULL, false, true, 'The AMA+ (Art Major Asian plus) Scholarship is the Korean government''s arts scholarship — an Official Development Assistance (ODA) program funded by the Ministry of Culture, Sports and Tourism and run by the Korea National University of Arts (K-Arts) for exceptionally talented arts students from developing countries. Since 2005 it has supported 400 students from 41 countries, with 261 graduates to date. It funds bachelor''s, master''s and master-level Artist Diploma study across K-Arts'' six schools — Music, Drama, Film/TV/Multimedia, Dance, Visual Arts and Korean Traditional Arts. The package covers full tuition for regular semesters, a monthly allowance of KRW 800,000 (the 2027 guide notes it may be increased under the regulations in force at admission), an economy airfare between the home country and Korea for entrance and for graduation, 6 or 3 months of intensive pre-entry Korean language training plus Korean courses during the degree, a KRW 200,000 settlement allowance on first entry, a graduation-thesis allowance of up to KRW 1,000,000 in the final semester, a Korean proficiency grant of KRW 100,000 a month (duration and criteria set against department language standards), National Health Insurance cover, and priority in school dormitory reservations. Only citizens of OECD DAC ODA-recipient countries may apply — Uzbekistan is on the guide''s 2027 eligible-countries list, in the lower-middle-income group — and both parents must also hold DAC-recipient citizenship.', 'Be a citizen of an OECD DAC ODA-recipient country (Uzbekistan is listed for the 2027 intake), with both parents also holding DAC-recipient citizenship; for dual citizens every citizenship held must be a DAC recipient. Bachelor''s applicants need a high school diploma or expected graduation (school systems shorter than 12 years are accepted where the Korean Ministry of Education recognizes equivalence); master''s applicants need a bachelor''s degree or higher; expected graduates for the 2027 intake had to complete by 23 February 2027. Every department sets its own Korean proficiency bar — TOPIK Level 3 to 6 across the 2027 admission units — and a valid TOPIK score must be submitted with the application; where TOPIK is unavailable, SKA/iSKA scores or King Sejong Institute / Korean-university language-institute certificates issued within two years can be considered, and applicants who pass document screening also sit K-Arts'' online iSKA-lite Korean test, which is complementary and never substitutes for TOPIK. English scores (TOEFL/IELTS/TEPS) are required only where a department asks for them and cannot replace TOPIK; holders of TOPIK 4 or above write the personal statement and study plan in Korean. Artistic talent is judged on the portfolio each department prescribes (unedited performance DVDs, scores, films, Korean-language writing and the like), unless the unit states no portfolio is required, and applicants must be in good health for long-term study. Apply to exactly one program and one department-major — dual applications are automatically rejected. Current or former beneficiaries of other Korean government scholarship degree programs (including GKS and AMA+ itself) generally cannot apply: the only exception is graduates who completed the previous degree with a CGPA of at least 90% (3.87/4.3) or a top-10% ranking and hold valid TOPIK Level 5 or above, applying for a higher degree (AMA+ graduates only 4 or more years after graduating; those who withdrew or were expelled can never reapply). Final grantees must post the original apostilled/consular-authenticated documents to K-Arts by the stated July deadline and enter Korea for the scheduled pre-entry Korean language training (TOPIK 5-6 holders are exempt, though a department may still require a Korean course); attendance below 85% at language training revokes admission, and quitting after entry requires refunding the scholarship, airfare, stipends and training costs. All inquiries are by email only (ama@karts.ac.kr) — no phone, SNS or in-person inquiries.', 'https://www.karts.ac.kr/en/karts/ama.do', '["OECD DAC recipient countries"]', 'Government scholarship', 'Full tuition (regular semesters only)', NULL, NULL, 'Priority in school dormitory reservations during K-Arts academic years', NULL, 'Korean proficiency is the language gate, not English: each department requires a valid TOPIK score at application (Level 3-6 across the 2027 admission units; SKA/iSKA or King Sejong Institute certificates can substitute where TOPIK is unavailable). TOEFL/IELTS/TEPS scores are required only by departments that ask for them and cannot replace TOPIK.', '["Application form (Form 1)","Personal statement (Form 2; in Korean if TOPIK Level 4+)","Study plan (Form 3; in Korean if TOPIK Level 4+)","Personal medical assessment (Form 4)","3 letters of recommendation signed within 6 months (Form 5; at least one recommender from the arts/culture sector; ODA-agency or Korean-embassy recommendations earn extra points)","Letter of consent / release of information (Form 6)","Diploma(s) - high school, and bachelor for master applicants - notarized translation, apostilled or Korean-consular authenticated","Official transcripts (high school and, for master applicants, university), apostilled or consular-authenticated","Passport copies of the applicant and both parents (or valid local ID)","Official nationality document (birth certificate or family-relationship certificate)","Original proof of language proficiency (TOPIK or equivalent; English scores when the department requires them)","Portfolio as prescribed by the department/major","Certificates of work experience, awards or other achievements (optional)"]', 'https://www.karts.ac.kr/en/karts/ama.do', NULL, NULL, 'not_published', NULL, NULL, '[{"batch":1,"name":"2027 intake","opening":"2026-05-05","deadline":"2026-05-15","announcement":"2026-06-30","status":"closed"}]', 'annual', 'Guideline released online in April and the application link opens in May (2027 intake: guideline April 2026; the 2028-intake round is expected on the same annual cycle but is not yet announced)', 'Mid-May (15 May 2026 for the 2027 intake; the next round''s dates are published with its guideline)', 'not_announced', '2026-11-01 10:00:00+05', '2026-11-01 10:00:00+05', 'verified', 10, 'https://www.karts.ac.kr/en/karts/ama.do', 'NEW in Enrichment Batch 44 (2026-11-01), written from first-hand reads of two official K-Arts documents: the AMA+ admissions page (source 3203, read in full - benefits list, eligibility, printed DAC eligible-countries list including Uzbekistan, 13 required documents) and the official 2027 AMA+ Admissions Guide PDF (source 3204, decision-relevant parts read: 2027 schedule, eligibility with reapplication restrictions, the guide''s own 2027 eligible-countries table with Uzbekistan in the lower-middle-income group, benefits table, and admission-unit tables for the six schools with per-department TOPIK levels). The scheme surfaced first-hand in the Other Scholarships section of the Study in Korea page read in Pass 137 (source 3197); duplicate checks found no AMA+/K-Arts record, and there is no universities row for K-Arts, so university_id is NULL and no university_scholarships side row was created. award_amount stores the published monthly allowance (KRW 800,000 per month, fixed basis, cf. 583 GKS); amount_usd_value 0 (KRW). min_gpa/min_ielts NULL: selection is portfolio/document-based with department-set TOPIK bars kept textual, and the only GPA figure in the guide (90% / 3.87 of 4.3) is a reapplication threshold for former Korean-government scholars, not an entry minimum. deadline_date NULL + not_published + rounds JSON: the 2027-intake round closed 15 May 2026 and the 2028 round is not yet announced; annual operation since 2005 (400 grantees from 41 countries, 261 alumni) evidences recurrence. Two source quirks recorded rather than smoothed over: the admissions webpage''s schedule block mixes cycles (2025 application against 2026 screening dates), so the guideline PDF governs all dates here; and the webpage states the Korean proficiency grant as KRW 100,000 a month ''for one year'' while the guide leaves its duration/criteria to department standards - the description follows the guide.', true, NULL, 800000, 'KRW', 'month', 'fixed');

